    std::tuple<uint8_t, uint8_t, uint8_t, uint8_t> lookup(colormap_t map, uint8_t gray)
    {
        const auto idx = static_cast<uint8_t>(map) * 1024 + gray * 4;
        return { LUT<uint8_t>[idx + 0], LUT<uint8_t>[idx + 1], LUT<uint8_t>[idx + 2], LUT<uint8_t>[idx + 3] };
    }

    template<typename T> const T *lut(colormap_t cmap) { return LUT<T> + static_cast<size_t>(cmap) * 1024; }

    template const uint8_t  *lut<uint8_t>(colormap_t);
    template const uint16_t *lut<uint16_t>(colormap_t);
    template const int16_t  *lut<int16_t>(colormap_t);
    template const uint32_t *lut<uint32_t>(colormap_t);
